import{_ as t,o,c as s,ag as a}from"./chunks/framework.BIas3y6W.js";const u=JSON.parse('{"title":"Week 6 Lab — From Spec to App","description":"","frontmatter":{"source":"weeks/06-spec-to-app/lab.md"},"headers":[],"relativePath":"weeks/06-spec-to-app/lab.md","filePath":"weeks/06-spec-to-app/lab.md"}'),r={name:"weeks/06-spec-to-app/lab.md"};function n(i,e,d,c,l,h){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="week-6-lab--from-spec-to-app" tabindex="-1">Week 6 Lab — From Spec to App <a class="header-anchor" href="#week-6-lab--from-spec-to-app" aria-label="Permalink to &quot;Week 6 Lab — From Spec to App&quot;">​</a></h1><p><strong>AI-use key:</strong> 🟢 AI on: use AI freely · 🟡 AI limited: the AI may comment or hint, but the work is yours · 🔴 AI off: close the AI tabs and work alone.</p><p>In <strong>Studio A</strong> you watch an app builder build from your spec, score the result against your own criteria, and compare notes with a partner who used a different builder. In <strong>Studio B</strong> you start the version you <strong>keep</strong>: plain files in your own repository, with the rules in their own module, a test written before each rule&#39;s code, and every step previewed in a Codespace before you commit it.</p><p><strong>You need:</strong> a laptop, your GitHub account, your Project 1 repository with <code>SPEC.md</code>, <code>TESTS.md</code> and the failing test from the week 5 homework, a sign-in for Google AI Studio or Bolt (your instructor tells you which), a chat assistant, and Canvas.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Nothing you paste today should contain personal data: not yours, and not anyone else&#39;s. On some free tiers, including Google AI Studio&#39;s, human reviewers may read what you type (<a href="./../../TOOLS.html">Tool Handout</a>). Your spec describes a tool, not a person.</p></div><p>Using a screen reader or only a keyboard? See the <a href="./../../resources/accessibility.html">screen reader and keyboard guide</a>. Working alone? Each pair activity has a <strong>Working alone?</strong> line.</p><hr><h2 id="studio-a--the-builder-bake-off-75-min" tabindex="-1">Studio A — The builder bake-off (75 min) <a class="header-anchor" href="#studio-a--the-builder-bake-off-75-min" aria-label="Permalink to &quot;Studio A — The builder bake-off (75 min)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time</th><th>Part</th><th>AI use</th><th>Core or if time</th></tr></thead><tbody><tr><td>0:00–0:25</td><td>Recap, concept talk and live demo</td><td>—</td><td></td></tr><tr><td>0:25–1:10</td><td><a href="#part-1--builder-bake-off-jigsaw-45-min">Part 1 — Builder bake-off jigsaw</a></td><td>🟢 AI on</td><td>Core</td></tr><tr><td>(while you wait)</td><td><a href="#part-2--spec-diff-5-min">Part 2 — Spec diff</a></td><td>🟡 AI limited</td><td>If time</td></tr><tr><td>1:10–1:15</td><td><a href="#checkpoint-share-5-min">Checkpoint share</a></td><td></td><td></td></tr></tbody></table><h3 id="part-1--builder-bake-off-jigsaw-45-min" tabindex="-1">Part 1 — Builder bake-off jigsaw (45 min) <a class="header-anchor" href="#part-1--builder-bake-off-jigsaw-45-min" aria-label="Permalink to &quot;Part 1 — Builder bake-off jigsaw (45 min)&quot;">​</a></h3><p>🟢 <strong>AI on.</strong></p><p><strong>Why:</strong> a browser app builder turns a description into a whole running app in minutes. You&#39;ll see what that buys you and what it costs (credits, code you can&#39;t read, lock-in) by feeding it <strong>your</strong> spec and scoring it against <strong>your</strong> criteria. In a jigsaw, each of you tests one builder, then you put the pieces together.</p><p><strong>How it works:</strong> your instructor gives you <strong>builder A</strong> or <strong>builder B</strong> and pairs you with someone who has the other one. You test only your builder, on your own spec. Then you compare scorecards. The class results board puts everyone&#39;s results side by side.</p><table tabindex="0"><thead><tr><th>Builder</th><th>Primary</th><th>Fallback (if blocked, down, under 18, or out of credits)</th></tr></thead><tbody><tr><td>A</td><td>Google AI Studio, <strong>Build</strong> mode (18+)</td><td>Bolt</td></tr><tr><td>B</td><td>Bolt</td><td>Lovable or v0 (check the <a href="./../../TOOLS.html">Tool Handout</a> for the current list)</td></tr></tbody></table><p>Open the <a href="./bake-off-scorecard.html">bake-off scorecard</a> and copy it into your notes. The rules: <strong>20 minutes, at most 3 prompts</strong> (the spec, then up to 2 fixes).</p><p><strong>Step 1 — Note your usage (2 min).</strong> Find where the builder shows your usage or remaining credits (usually under your account, settings or plan menu). Write the number in section 3 of the scorecard. Menus move: if you can&#39;t find it in two minutes, ask the builder &quot;Where can I see my usage or remaining credits?&quot; and move on.</p><p><strong>Step 2 — Paste the prompt (3 min).</strong> Use this framing prompt, followed by your full <code>SPEC.md</code> (copy it from your repository):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Build the app described in the spec below.</span></span>
<span class="line"><span>Context: This is a one-page spec for a single-user tool. Its acceptance criteria (WHEN … THE APP SHALL …) are how I will judge your result.</span></span>
<span class="line"><span>Constraints: Follow the spec&#39;s Constraints and Out of scope sections. No login, no accounts, no cloud database: save data in the browser only.</span></span>
<span class="line"><span>Done when: Every MUST criterion passes when I try it in the preview.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[paste your SPEC.md here]</span></span></code></pre></div><p>In Google AI Studio, open <strong>Build</strong> from the left-hand menu and paste into the box that asks what you want to build. In Bolt, paste into the main prompt box. Building takes a few minutes: meanwhile, copy your criteria into section 1 of the scorecard.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>If a builder asks to connect to your GitHub or Google account, read what access it wants. You don&#39;t need to connect anything today.</p></div><p><strong>Step 3 — Test against your criteria, not your eyes (15 min).</strong> Go down your acceptance criteria <strong>in order</strong> and try each one in the preview. Mark ✅ passes, <strong>X</strong> fails, <strong>~</strong> partly or <strong>n/t</strong> not tested, and write what actually happened in Notes. Your manual tests in <code>TESTS.md</code> already say what to try. Then try one edge case that isn&#39;t in your spec.</p><p>If a MUST criterion fails, you may spend a fix prompt on it. Say what works first, then name the failing criterion:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AC1–AC3 pass. AC4 fails. Steps: I pressed Stop after 1 minute 10 seconds. Expected: a new session at the top of the log saying &quot;1 min&quot;. Actual: nothing was added. Fix only this. Don&#39;t change anything else.</span></span></code></pre></div><p>After two fix prompts, stop, even if something still fails. That&#39;s data for your scorecard, not your failure.</p><p><strong>Step 4 — Look under the hood (8 min).</strong> Open the builder&#39;s code or files view and fill in section 2 of the scorecard:</p><ul><li>What files did it create? Is there a <code>package.json</code>? What libraries does it list?</li><li>Files ending <code>.tsx</code> or <code>.jsx</code> usually mean <strong>React</strong>, a popular JavaScript <a href="./../../resources/glossary.html#framework">framework</a>. A <code>&quot;build&quot;</code> script means the code has to be converted before a browser can run it.</li><li>Search the code for <code>localStorage</code>. Did it follow your data constraint, or did it add a database or a login?</li><li>Did it write any tests? Where would your logic plan&#39;s rules live in this code?</li><li>Find the <strong>export</strong> options (to GitHub, or a ZIP download). Write down what they&#39;re called. Don&#39;t export yet.</li></ul><p><strong>Step 5 — Note your usage again (2 min)</strong> and finish section 3.</p><p><strong>Step 6 — Compare with your partner (15 min).</strong> Show each other your scorecards. Copy your partner&#39;s totals into section 5 (&quot;My partner&#39;s builder&quot;). Then talk:</p><ol><li>Which builder passed a bigger share of its MUST criteria? Was it the one that <em>looked</em> better?</li><li>Did either builder add a login, a database or a feature from the Out of scope list?</li><li>Which code could either of you explain line by line?</li></ol><p>Add your line to the class results board (the format is in section 5 of the scorecard).</p><p>✅ <strong>Checkpoint:</strong> sections 1–5 of your scorecard are filled in, and your line is on the class results board.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>Out of credits?</strong> Stop. Don&#39;t create a second account to get more. Switch to the fallback builder, or score your partner&#39;s builder with your own criteria. See <a href="./../../resources/troubleshooting.html#i-ran-out-of-free-credits">I ran out of free credits</a>.</p></div><p><strong>Working alone?</strong> Run both builders if your credits allow (allow 40 minutes), or compare your result with the class results board your instructor posts.</p><h3 id="part-2--spec-diff-5-min" tabindex="-1">Part 2 — Spec diff (5 min) <a class="header-anchor" href="#part-2--spec-diff-5-min" aria-label="Permalink to &quot;Part 2 — Spec diff (5 min)&quot;">​</a></h3><p><strong>If time</strong>, while you wait for your partner or the board. 🟡 AI limited: you write the change.</p><p>Pick one failure from Step 3 that your spec could have prevented: a criterion the builder read differently from you, or something it added that your Out of scope list didn&#39;t rule out. Change that line in <code>SPEC.md</code> on GitHub, update &quot;Last updated&quot;, and commit the change on its own with a message that says why, for example <code>Say &quot;Monday to Sunday&quot; in AC7 after the bake-off</code>.</p><h3 id="checkpoint-share-5-min" tabindex="-1">Checkpoint share (5 min) <a class="header-anchor" href="#checkpoint-share-5-min" aria-label="Permalink to &quot;Checkpoint share (5 min)&quot;">​</a></h3><p>Your instructor reads out the results board. Two pairs say which criterion failed in <strong>both</strong> builders, and whether the spec was the cause.</p><p><strong>Before you leave Studio A:</strong></p><ul><li>☐ Your scorecard, sections 1–5, is saved somewhere safe. It goes into <code>docs/</code> for homework.</li><li>☐ Your line is on the class results board.</li></ul><h3 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Problem</th><th>Try this</th></tr></thead><tbody><tr><td>A builder won&#39;t let me in (age, region, sign-up)</td><td>Use the fallback in the Part 1 table. Under-18 and EEA/UK cohorts: your instructor follows the course variants</td></tr><tr><td>The builder added a login, a database or features I didn&#39;t ask for</td><td>That&#39;s a finding. Record it in section 2 of the scorecard. Don&#39;t spend prompts removing it</td></tr><tr><td>The builder&#39;s preview is blank or shows an error</td><td>Wait 30 seconds and refresh it. If it&#39;s still broken, use one fix prompt and paste the exact error text</td></tr><tr><td>Reloading the builder&#39;s preview loses my data</td><td>Some previews run inside a frame that doesn&#39;t keep saved data like a real site. Write what you saw and mark the criterion <strong>n/t</strong> (the scorecard explains)</td></tr><tr><td>I can&#39;t find the code or files view</td><td>Look for a &quot;Code&quot;, &quot;Files&quot; or <code>&lt;/&gt;</code> button near the preview. Menus move: ask the builder where its files view is</td></tr></tbody></table><hr><h2 id="studio-b--start-project-1-75-min" tabindex="-1">Studio B — Start Project 1 (75 min) <a class="header-anchor" href="#studio-b--start-project-1-75-min" aria-label="Permalink to &quot;Studio B — Start Project 1 (75 min)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time</th><th>Part</th><th>AI use</th><th>Core or if time</th></tr></thead><tbody><tr><td>0:00–0:05</td><td>Show and tell: what the results board says</td><td>—</td><td></td></tr><tr><td>0:05–0:10</td><td>Mini-demo: red, then green</td><td>—</td><td></td></tr><tr><td>0:10–0:50</td><td><a href="#part-3--start-project-1-in-a-codespace-40-min">Part 3 — Start Project 1 in a Codespace</a></td><td>🟢 AI on · 🟡 AI limited for tests</td><td>Core</td></tr><tr><td>0:50–1:05</td><td><a href="#part-4--keep-building-15-min">Part 4 — Keep building</a></td><td>🟢 AI on · 🟡 AI limited for tests</td><td>Core</td></tr><tr><td>1:05–1:15</td><td><a href="#exit-ticket-10-min">Exit ticket</a></td><td>🔴 AI off</td><td></td></tr></tbody></table><h3 id="part-3--start-project-1-in-a-codespace-40-min" tabindex="-1">Part 3 — Start Project 1 in a Codespace (40 min) <a class="header-anchor" href="#part-3--start-project-1-in-a-codespace-40-min" aria-label="Permalink to &quot;Part 3 — Start Project 1 in a Codespace (40 min)&quot;">​</a></h3><p>🟢 <strong>AI on</strong> for the app code, in a chat assistant: you paste its code into your files yourself. 🟡 <strong>AI limited</strong> for your tests: you choose the cases and the expected results, and the AI may explain syntax or an error.</p><p><strong>Why:</strong> the builder&#39;s app lives on someone else&#39;s platform, in code you can&#39;t read yet. The version you <strong>keep</strong> is plain files in your own repository. A <strong><a href="./../../resources/glossary.html#codespace">Codespace</a></strong> lets you see each change running <em>before</em> you commit it, which is the Safe Loop&#39;s order: test, read, then save. And because the rules sit in their own module, a test can check them in a second, every time.</p><p>This is the layout you&#39;re building toward (Sam&#39;s <a href="https://github.com/Boyu-Zhang-UOI/vc101-rescue-study-timer" target="_blank" rel="noreferrer">rescue starter</a> uses it too):</p><table tabindex="0"><thead><tr><th>File</th><th>What it holds</th></tr></thead><tbody><tr><td><code>index.html</code></td><td>The page&#39;s structure. It loads <code>app.js</code> with <code>&lt;script type=&quot;module&quot; src=&quot;app.js&quot;&gt;&lt;/script&gt;</code></td></tr><tr><td><code>style.css</code></td><td>How the page looks</td></tr><tr><td><code>app.js</code></td><td>The only file that touches the page (<code>document</code>) and <code>localStorage</code>. It imports the rules from <code>lib/</code></td></tr><tr><td><code>lib/[module].js</code></td><td>The rules from your logic plan, as <a href="./../../resources/glossary.html#pure-function">pure functions</a>, shared with <code>export</code></td></tr><tr><td><code>tests/[module].test.js</code></td><td>Your tests, which import the same functions. You started this last week</td></tr><tr><td><code>package.json</code></td><td>Tells Node the project uses modules and that <code>npm test</code> runs <code>node --test</code>. Nothing to install</td></tr></tbody></table><ol><li><p><strong>Open a Codespace (4 min).</strong> On your Project 1 repository, click the green <strong>Code</strong> button → <strong>Codespaces</strong> tab → <strong>Create codespace on main</strong> (or reopen your week 5 one from <a href="https://github.com/codespaces" target="_blank" rel="noreferrer">github.com/codespaces</a>).</p></li><li><p><strong>Start the preview (3 min).</strong> Click in the terminal at the bottom and type:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http.server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8000</span></span></code></pre></div><p>A pop-up says your application is running on port 8000: click <strong>Open in Browser</strong>. (No pop-up? Open the <strong>Ports</strong> tab next to the terminal and click the globe icon next to port 8000.) For now you&#39;ll see a list of files (<code>README.md</code>, <code>SPEC.md</code>…). That&#39;s normal until <code>index.html</code> exists. Keep this tab open: it&#39;s your preview. Then open a <strong>second terminal</strong> with the <strong>+</strong> button in the terminal panel, for <code>npm test</code>.</p></li><li><p><strong>Check your red test (3 min).</strong> In the second terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>Your week 5 test should fail with <strong>Cannot find module</strong> and <code>fail 1</code>. No test yet? Do <a href="./../05-spec-first/homework.html">week 5 homework task 5</a> now: it&#39;s the first check of the day.</p></li><li><p><strong>Describe and Plan (8 min).</strong> Open a <strong>fresh</strong> chat. Paste this prompt, your test file and your <code>SPEC.md</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Help me build version 1 of the app in my spec below, one small step at a time.</span></span>
<span class="line"><span>Context: I can program in [Python, or your language] but I&#39;m new to JavaScript and the web. The app is a static site on GitHub Pages: index.html, style.css and app.js, with the rules (checking input, calculations, sorting, dates) as pure functions in lib/. My first test file is below; Node runs it with npm test. My spec is below that.</span></span>
<span class="line"><span>Constraints: Plain HTML, CSS and JavaScript (ES modules) only: no frameworks, no libraries, no build step, no login, no database, no requests to other websites. Functions in lib/ take everything they need as arguments, including today&#39;s date, and never use document, localStorage or the clock; app.js is the only file that does, and it imports from lib/. Use exactly the function names and arguments my test uses. Never change my test files. Use textContent, not innerHTML, for anything the user typed. Short comments. Don&#39;t write any code yet.</span></span>
<span class="line"><span>Done when: You have proposed a plan of 4–6 small steps. Each step names the acceptance criteria it covers (by ID), any lib/ functions it adds, and ends with something I can test: npm test, the preview, or both.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[paste your test file here]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[paste your SPEC.md here]</span></span></code></pre></div><p>If you have a wireframe image, attach it too: showing beats describing (one of the <a href="./../../resources/prompt-patterns.html#the-three-habits">three habits</a>). Read the plan and edit it: reorder steps, merge or split them, and remove anything out of scope. Step 1 should be small, for example the page structure plus the function your red test checks. Tell the chat your edited plan.</p></li><li><p><strong>Check first (5 min).</strong> Before you ask for step 1, write its checks:</p><ul><li><strong>Automated, where the step has a rule.</strong> Your red test covers the first function. If step 1 adds another rule from your logic plan, add its test cases now, in your own words, and run <code>npm test</code> again: red. <a href="./../05-spec-first/homework.html">Sam&#39;s test</a> and the rescue starter&#39;s <code>tests/</code> folder are models.</li><li><strong>Manual, for what the page shows.</strong> Open <code>PROMPTS.md</code> and start an entry for step 1: which criteria it covers, what you&#39;ll click or type, and what you expect to see. Your manual tests in <code>TESTS.md</code> are most of the work already.</li></ul><p>Writing the checks before you see the code keeps them honest (<a href="./../../resources/safe-loop.html#check-first">check first</a>).</p></li><li><p><strong>Step (5 min).</strong> Ask for step 1 only:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Let&#39;s do step 1 only. Give me the complete contents of each file this step creates or changes, each in its own code block with the file name above it. Don&#39;t change my test files.</span></span></code></pre></div><p>In the Explorer (the file list on the left), click the <strong>New File</strong> icon to create each file the first time (typing <code>lib/validate.js</code> as the name creates the folder too), paste in its code, and save (Ctrl+S, or Cmd+S on a Mac).</p></li><li><p><strong>Test (5 min).</strong> In the second terminal, run <code>npm test</code>: your test should now pass (✔, <code>fail 0</code>). Then reload the preview tab, run your manual check, and try one edge case.</p><p>Still red? Read the failure: which test, what it expected, and what came back. Give the chat exactly that: &quot;The test &#39;an empty name is refused with the AC2 message&#39; fails: expected &#39;Type a new subject name.&#39;, got &#39;&#39;. Fix the code in lib/, not the test.&quot;</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>Never let the AI change a test to make it pass.</strong> If a test seems wrong, check it against <code>SPEC.md</code>, fix it yourself, and say why in <code>PROMPTS.md</code>.</p></div><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Blank page, or nothing happens when you click?</strong> Open DevTools (F12, or Ctrl+Shift+I; Cmd+Option+I on a Mac) and click the <strong>Console</strong> tab. Read the red line before you do anything else. Paste that exact error into the chat, with what you did and what you expected. Next week you&#39;ll learn to read these yourself. More: <a href="./../../resources/troubleshooting.html#my-page-is-blank">My page is blank</a>.</p></div></li><li><p><strong>Read and teach back (3 min).</strong> Read the new code. Ask the chat to explain any line you can&#39;t explain (&quot;Explain these lines to someone who knows Python but not JavaScript&quot;). Then write a <strong>teach-back</strong> under the step in <code>PROMPTS.md</code>: two or three sentences, in your own words, saying what changed and why it works (<a href="./../../resources/safe-loop.html#teach-back">teach back</a>).</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Reading JavaScript with Python eyes.</strong> <code>===</code> is the comparison you want (<code>==</code> converts types first, so <code>&quot;1&quot; == 1</code> is true). <code>const</code> and <code>let</code> declare variables (<code>const</code> can&#39;t be reassigned). <code>null</code> and <code>undefined</code> both mean &quot;no value&quot;. Braces, not indentation, mark blocks. Arrays and objects work like Python&#39;s lists and dicts, but <code>===</code> on two of them asks whether they are the <em>same</em> one.</p></div></li><li><p><strong>Commit (2 min).</strong> Click the <strong>Source Control</strong> icon on the left. Type a message that says what changed, such as <code>Add subject check and page skeleton (AC1, AC2)</code>, press Enter twice, and add the line <code>Assisted-by: Gemini</code> (or the tool you used). Click <strong>Commit</strong> (choose <strong>Yes</strong> if it asks to stage all changes), then <strong>Sync Changes</strong> to push it to GitHub.</p></li></ol><p>✅ <strong>Checkpoint:</strong> <code>npm test</code> shows your test passing; step 1 runs in your preview and passes its manual check; it&#39;s committed and pushed; and <code>PROMPTS.md</code> has the step&#39;s checks and teach-back.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Three things change because <code>app.js</code> is a module. (1) <code>onclick=&quot;someFunction()&quot;</code> in your HTML stops working, because module functions aren&#39;t global: use <code>addEventListener</code> in <code>app.js</code>. (2) You can&#39;t type your variable names into the Console; use <code>console.log</code> instead. (3) Modules only work through a web server (your preview or GitHub Pages), not by opening <code>index.html</code> from your computer&#39;s files.</p></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The preview address (ending in <code>.app.github.dev</code>) is private to you. To show someone your app, share your GitHub Pages address instead.</p></div><h3 id="part-4--keep-building-15-min" tabindex="-1">Part 4 — Keep building (15 min) <a class="header-anchor" href="#part-4--keep-building-15-min" aria-label="Permalink to &quot;Part 4 — Keep building (15 min)&quot;">​</a></h3><p>🟢 <strong>AI on</strong> for the app code · 🟡 <strong>AI limited</strong> for your tests.</p><p>Repeat the loop for steps 2, 3 and onward: <strong>check first (a test for each new rule, a written manual check for the rest) → ask for one step → paste and save → <code>npm test</code> and the preview → read and teach back → commit.</strong> Start with the criteria that make the app usable at all (adding and showing items, then saving across a reload), and leave the polish until later.</p><ul><li><strong>The two-strikes rule:</strong> if two attempts to fix the same problem fail, stop, start a fresh chat, paste your spec, your test file and your current <code>app.js</code>, and describe what you tried, the exact error and what you expected (<a href="./../../resources/safe-loop.html#the-two-strikes-rule">The Safe Loop</a>).</li><li><strong>Keep the rules out of <code>app.js</code>.</strong> If the AI puts a calculation or a check inside an event listener, ask it to move the rule into <code>lib/</code> as a pure function and call it from <code>app.js</code>, then write the test.</li><li><strong>Before you leave,</strong> open your GitHub Pages address (<strong>Settings</strong> → <strong>Pages</strong>) and check that the committed version works there too. Pages takes a minute or two to update after you push. Then stop your Codespace (<a href="./../../setup/codespaces.html#stop-and-delete-codespaces">stop and delete codespaces</a>).</li></ul><p>✅ <strong>Checkpoint:</strong> at least one step is committed, pushed and showing on your GitHub Pages site.</p><h3 id="exit-ticket-10-min" tabindex="-1">Exit ticket (10 min) <a class="header-anchor" href="#exit-ticket-10-min" aria-label="Permalink to &quot;Exit ticket (10 min)&quot;">​</a></h3><p>The week 6 exit ticket: 🔴 AI off, graded on completion, not correctness. The first question looks back at your week 4 work; answer it from memory, without opening your files.</p><h3 id="troubleshooting-1" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting-1" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Problem</th><th>Try this</th></tr></thead><tbody><tr><td>The chat keeps giving me React, or asks me to run <code>npm install</code></td><td>Start a fresh chat. Put &quot;Plain HTML, CSS and JavaScript only, no build step, no libraries&quot; at the top of the Constraints. <code>npm test</code> needs nothing installed</td></tr><tr><td>The code stops halfway through</td><td>Ask for one file at a time: &quot;Now give me only the full app.js&quot;</td></tr><tr><td>The preview shows a list of files, not my app</td><td>There&#39;s no <code>index.html</code> yet, or it&#39;s misspelled (it must be lowercase, in the top folder). The server shows the folder it was started in</td></tr><tr><td>The preview shows an old version</td><td>Save the file (a dot on its tab means unsaved), then hard-reload with Ctrl+Shift+R (Cmd+Shift+R on a Mac)</td></tr><tr><td><code>Address already in use</code> when starting the server</td><td>A server is already running. Find its terminal and press Ctrl+C, or use another port: <code>python3 -m http.server 8001</code></td></tr><tr><td><code>npm test</code> shows <code>tests 0</code></td><td>Node didn&#39;t find your test file. Its name must end in <code>.test.js</code></td></tr><tr><td><code>npm test</code> still says it cannot find the module after the step</td><td>Check the folder (<code>lib</code>, at the top level) and the spelling of the file name and the <code>import</code> line, including <code>.js</code></td></tr><tr><td><code>npm test</code> complains about JSON</td><td>A comma or quote is missing in <code>package.json</code>. Compare it with the week 5 homework, character by character</td></tr><tr><td><code>Cannot use import statement outside a module</code></td><td>In Node: <code>package.json</code> needs <code>&quot;type&quot;: &quot;module&quot;</code>. In the browser: the script tag needs <code>type=&quot;module&quot;</code></td></tr><tr><td>The Console says a module &quot;failed to load&quot; or was blocked</td><td>You opened <code>index.html</code> as a file. Use the preview tab (or Pages), and check the <code>import</code> path starts with <code>./</code></td></tr><tr><td>A button does nothing, with no error</td><td>Your HTML probably uses <code>onclick=&quot;…&quot;</code>. See the module warning after step 9</td></tr><tr><td>The AI changed my test so it passes</td><td>Undo that file (in Source Control, right-click it → <strong>Discard Changes</strong>), and tell the chat: &quot;Don&#39;t change the tests; fix the code.&quot;</td></tr><tr><td>My Pages site shows a 404 page</td><td>Check that <code>index.html</code> is in the top folder and that you pushed (<strong>Sync Changes</strong>). Wait two minutes; the <strong>Actions</strong> tab shows whether it&#39;s still deploying (<a href="./../../resources/troubleshooting.html#github-pages-shows-404">GitHub Pages shows 404</a>)</td></tr><tr><td>The Codespace won&#39;t start, or I&#39;m out of hours</td><td>Stop other codespaces at <a href="https://github.com/codespaces" target="_blank" rel="noreferrer">github.com/codespaces</a>. Meanwhile, edit in github.dev (press <code>.</code> on your repository page) and test on Pages after each commit; <code>npm test</code> waits until you have a terminal again</td></tr></tbody></table><hr><h2 id="before-you-leave-studio-b" tabindex="-1">Before you leave Studio B <a class="header-anchor" href="#before-you-leave-studio-b" aria-label="Permalink to &quot;Before you leave Studio B&quot;">​</a></h2><ul><li>☐ Your scorecard, sections 1–5, is saved somewhere safe (it goes into <code>docs/</code> for homework).</li><li>☐ At least one step of Project 1 is committed, pushed and live on GitHub Pages, and <code>npm test</code> shows at least one passing test.</li><li>☐ <code>PROMPTS.md</code> has the builder prompt, the plan prompt, and a check and teach-back for each step so far.</li><li>☐ Your Codespace is stopped.</li><li>☐ Homework: <a href="./homework.html">homework</a>. The Verdict goes on Canvas, written without AI.</li></ul>`,66)])])}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
